function roleNotifications(){
  const account=sessionAccount();
  if(state.role==='donor'){
    const appealsNotifications=pendingMatchedAppeals().map(appeal=>({title:`نداء ${appeal.bloodType} من ${appeal.org}`,detail:`${appeal.units} وحدات · ${appeal.urgency} · ${appealDate(appeal.neededAt)}`}));
    const voluntaryNotifications=voluntaryDonationRequests.filter(request=>request.donorId===account?.id).slice(0,10).map(request=>({title:`طلب التبرع ${request.id}: ${request.status}`,detail:request.appointmentAt?`${request.institution} · الموعد ${appealDate(request.appointmentAt)}`:request.institution}));
    return[...voluntaryNotifications,...appealsNotifications]
  }
  if(isInstitutionRole(account?.role)&&!isInstitutionApproved(account)){const status=institutionApprovalStatus(account);return[{title:status==='rejected'?'تم رفض طلب اعتماد المؤسسة':'طلب اعتماد المؤسسة قيد المراجعة',detail:status==='rejected'?`سبب الرفض: ${account.rejectionReason||'لم يُذكر سبب'}`:`أُرسل إلى مشرف الصحة في ${appealDate(account.submittedAt||account.createdAt)}`}]} 
  const approvalAlerts=state.role==='supervisor'?pendingInstitutions().map(item=>({title:`طلب اعتماد جديد: ${item.organization}`,detail:`${item.institutionProfile?.institutionType||roles[item.role]?.label} · ${item.institutionProfile?.governorate||'غير محدد'}`})):isInstitutionRole(account?.role)&&account.reviewedAt?[{title:'تم اعتماد المؤسسة وتفعيل الحساب',detail:`اعتمد الطلب بواسطة ${account.reviewedBy||'مشرف الصحة'} في ${appealDate(account.reviewedAt)}`}]:[];
  const voluntaryAlerts=voluntaryRequestsForView().slice(0,10).map(request=>({title:`تبرع طوعي: ${request.donorName} · ${request.status}`,detail:`${request.institution} · فصيلة ${request.bloodType}${request.appointmentAt?` · ${appealDate(request.appointmentAt)}`:''}`}));
  const scoped=requestsForRole().filter(request=>state.role==='supervisor'||request.org===currentOrganizationName()||request.target===currentOrganizationName());return[...approvalAlerts,...voluntaryAlerts,...scoped.slice(0,20).map(request=>({title:`الطلب ${request.id}: ${request.status}`,detail:`${request.org} ← ${request.target} · ${request.units} وحدات ${request.type}`}))]
}
function notifications(){if(state.role==='donor'){const matching=pendingMatchedAppeals(),direct=voluntaryDonationRequests.filter(request=>request.donorId===sessionAccount()?.id);return `${heading('الإشعارات','تابع نداءات الدم ومواعيد طلبات تبرعك')}<article class="card">${direct.length?`<h3 class="section-subtitle">طلبات التبرع الطوعي</h3>${voluntaryDonationRequestsContent(direct)}`:''}${matching.length?`<h3 class="section-subtitle">نداءات متوافقة</h3>${appealList(matching,true)}`:''}${!direct.length&&!matching.length?emptyContent('لا توجد إشعارات','ستظهر هنا مواعيد طلباتك ونداءات التبرع المتوافقة.'):''}</article>`}const rows=roleNotifications();return `${heading('الإشعارات','آخر حالات الطلبات المرتبطة بحسابك')}<article class="card">${rows.length?`<div class="list">${rows.map(item=>`<div class="list-item notification unread"><span class="list-item-icon">♢</span><div class="list-item-main"><strong>${item.title}</strong><p>${item.detail}</p></div></div>`).join('')}</div>`:emptyContent('لا توجد إشعارات','ستظهر هنا تغييرات الطلبات والعمليات المرتبطة بحسابك.')}</article>`}
function render(){refreshAppealStatuses();const account=sessionAccount(),restricted=isInstitutionRole(account?.role)&&!isInstitutionApproved(account),allowedRestrictedPages=['dashboard','profile','notifications'];if(restricted&&!allowedRestrictedPages.includes(state.page))state.page='dashboard';setIdentity();renderNav();const title=restricted&&state.page==='dashboard'?'حالة طلب الاعتماد':navByRole[state.role].find(x=>x[0]===state.page)?.[2]||'لوحة التحكم';$('#page-title').textContent=title;$('#today-label').textContent=dateLabel();let html;if(restricted&&state.page==='dashboard')html=institutionApprovalWorkspace();else if(state.page==='dashboard')html=state.role==='supervisor'?supervisorDashboard():state.role==='donor'?donorDashboard():state.role==='hospital'?requestOnlyHospitalDashboard():genericDashboard();else if(state.page==='new-request'){html=listPage('requests');setTimeout(()=>openModal('request'),0)}else if(state.page==='notifications')html=notifications();else html=listPage(state.page);$('#page-content').innerHTML=html;$('#notify-count').textContent=String(roleNotifications().length);window.scrollTo(0,0)}
function requestActionButtons(request){
  const org=currentOrganizationName();
  if(request.org===org){
    if(request.status==='قيد الاستجابة')return `<button class="danger-btn" data-action="cancel-request" data-id="${request.id}">إلغاء الطلب</button>`;
    if(request.status==='تم الإرسال بانتظار الاستلام')return canManageEmployees()?`<button class="primary-btn" data-action="receive-request" data-id="${request.id}">تم استلام الوحدات</button>`:'<span class="status amber">بانتظار تأكيد الممثل الرسمي</span>';
  }
  if(request.target===org&&['hospital_bloodbank','bloodbank'].includes(state.role)){
    if(request.status==='قيد الاستجابة')return `<button class="primary-btn" data-action="accept-request" data-id="${request.id}">قبول الطلب</button><button class="danger-btn" data-action="reject-request" data-id="${request.id}">رفض الطلب</button>`;
    if(request.status==='مقبول بانتظار الإرسال')return `<button class="primary-btn" data-action="send-request" data-id="${request.id}">تم إرسال الوحدات</button>`;
  }
  return '';
}
