  if(institutionApprovalStatus(account)==='pending'){toast('لا يمكن تعديل الطلب أثناء مراجعته');return}
  const p=currentInstitutionProfile();if(!p)return;
  const types=['مستشفى مركزي','مستشفى ميداني','مركز صحي','جمعية بنك دم','مركز دم مستقل'],scopes=[['blood_request_only','hospital','مؤسسة تطلب الدم فقط'],['hospital_blood_bank','hospital_bloodbank','مستشفى لديه بنك دم'],['central_blood_bank','bloodbank','بنك الدم المركزي']],documents=p.documents||{};
  showCustomModal('تعديل بيانات المؤسسة',institutionApprovalStatus(account)==='rejected'?'تصحيح طلب الاعتماد':'بيانات الحساب',`<form id="institution-form"><div class="form-grid"><label class="field full">اسم المؤسسة<input name="name" value="${p.name}" required></label><label class="field">نوع المؤسسة<select name="institutionType">${types.map(type=>`<option ${type===p.institutionType?'selected':''}>${type}</option>`).join('')}</select></label><label class="field">نطاق العمل<select name="serviceScope" required>${scopes.map(([value,role,label])=>`<option value="${value}" ${role===account.role?'selected':''}>${label}</option>`).join('')}</select></label><label class="field">رقم الترخيص<input name="license" value="${p.license}" required></label><label class="field">المحافظة<input name="governorate" value="${p.governorate}" required></label><label class="field full">العنوان<input name="address" value="${p.address}" required></label><label class="field">هاتف المؤسسة<input name="phone" value="${p.phone}" required></label><label class="field">بريد المؤسسة<input name="email" type="email" value="${p.email}" required></label><label class="field full">اسم الممثل الرسمي<input name="representativeName" value="${p.representativeName}" required></label><label class="field">الصفة الوظيفية<input name="representativeRole" value="${p.representativeRole}" required></label><label class="field">هاتف الممثل<input name="representativePhone" value="${p.representativePhone}" required></label><label class="field full">بريد الممثل<input name="representativeEmail" type="email" value="${p.representativeEmail}" required></label><div class="field full"><strong>تحديث الوثائق (اختياري)</strong><small class="muted">اترك الملف فارغًا للاحتفاظ بالوثيقة الحالية.</small></div><label class="field">رخصة مزاولة العمل<input name="licenseDocument" type="file" accept=".pdf,.jpg,.jpeg,.png"><small>${documents.license?.name||'لا توجد معلومات ملف'}</small></label><label class="field">خطاب تفويض الممثل<input name="authorizationDocument" type="file" accept=".pdf,.jpg,.jpeg,.png"><small>${documents.authorization?.name||'لا توجد معلومات ملف'}</small></label><label class="field">شهادة الجودة<input name="qualityDocument" type="file" accept=".pdf,.jpg,.jpeg,.png"><small>${documents.quality?.name||'لا توجد معلومات ملف'}</small></label></div><div class="modal-actions"><button class="primary-btn" type="submit">حفظ التعديلات</button><button class="secondary-btn" type="button" data-action="close-modal">إلغاء</button></div></form>`)
